// >>> LAYER 0 TRANSLATION BEGIN <<<
namespace L0 {
    static constexpr int SIM_W = 120;
    static constexpr int SIM_H = 120;
    static constexpr int MAX_AGENTS = 800;

    struct Agent {
        float x;
        float y;
    };

    static float* trailMap = nullptr;
    static Agent agents[MAX_AGENTS];
    static float timeAcc = 0.0f;

    // Helper for setup and update random generation
    static inline float randFloat() {
        return (float)rand() / (float)RAND_MAX;
    }

    void setup() {
        if (!trailMap) {
            trailMap = PFMem::allocFloats(SIM_W * SIM_H);
        }

        PFMath::buildSinLUT();

        const float midX = SIM_W * 0.5f;
        const float midY = SIM_H * 0.5f;

        for (int i = 0; i < MAX_AGENTS; i++) {
            agents[i].x = midX;
            agents[i].y = midY;
        }
    }

    void update(float dt, const InputFrame& input) {
        if (!trailMap) return;

        timeAcc += dt;
        if (timeAcc > TWO_PI) {
            timeAcc -= TWO_PI;
        }

        const float numAgentsParam = knobVal[0];
        const float turboParam = knobVal[1];
        const float voidSizeParam = knobVal[2];
        const float wiggleParam = knobVal[3];

        const int numAgents = (int)fminf(fmaxf(numAgentsParam, 0.0f), (float)MAX_AGENTS);
        const int turbo = (int)fmaxf(turboParam, 0.0f);

        const float midX = SIM_W * 0.5f;
        const float midY = SIM_H * 0.5f;

        // 1. MOVEMENT LOGIC
        for (int g = 0; g < turbo; g++) {
            for (int i = 0; i < numAgents; i++) {
                Agent& a = agents[i];

                const bool isWiggling = randFloat() < wiggleParam;

                if (isWiggling) {
                    a.x += (randFloat() - 0.5f) * 3.0f;
                    a.y += (randFloat() - 0.5f) * 3.0f;
                } else {
                    if (randFloat() < 0.5f) {
                        if (a.x < midX - voidSizeParam) {
                            a.x += (randFloat() < 0.9f ? -1.0f : 1.0f);
                        } else if (a.x > midX + voidSizeParam) {
                            a.x += (randFloat() < 0.9f ? 1.0f : -1.0f);
                        } else {
                            a.x += (randFloat() - 0.5f) * 2.0f;
                        }
                    } else {
                        if (a.y < midY - voidSizeParam) {
                            a.y += (randFloat() < 0.9f ? -1.0f : 1.0f);
                        } else if (a.y > midY + voidSizeParam) {
                            a.y += (randFloat() < 0.9f ? 1.0f : -1.0f);
                        } else {
                            a.y += (randFloat() - 0.5f) * 2.0f;
                        }
                    }
                }

                // Auto-Respawn
                if (a.x < 0.0f || a.x >= SIM_W || a.y < 0.0f || a.y >= SIM_H || randFloat() < 0.015f) {
                    a.x = midX + (randFloat() - 0.5f) * (voidSizeParam * 1.2f);
                    a.y = midY + (randFloat() - 0.5f) * (voidSizeParam * 1.2f);
                }

                int ix = (int)a.x;
                int iy = (int)a.y;
                if (ix >= 0 && ix < SIM_W && iy >= 0 && iy < SIM_H) {
                    trailMap[ix + iy * SIM_W] = 1.0f;
                }
            }
        }

        // 2. DECAY
        const int totalPixels = SIM_W * SIM_H;
        for (int i = 0; i < totalPixels; i++) {
            trailMap[i] *= 0.96f;
        }
    }

    void draw() {
        if (!trailMap) return;

        const float sinTimeTerm = 80.0f + PFMath::fastSin(timeAcc) * 20.0f;

        for (int y = 0; y < FRAME_H; y++) {
            const int sy = (y * SIM_H) / FRAME_H;
            const float bFactor = 50.0f + ((float)sy / (float)SIM_H) * 205.0f;
            const int rowOffset = sy * SIM_W;

            for (int x = 0; x < FRAME_W; x++) {
                const int sx = (x * SIM_W) / FRAME_W;
                const float val = trailMap[sx + rowOffset];

                if (val > 0.01f) {
                    const float gFactor = 50.0f + ((float)sx / (float)SIM_W) * 205.0f;

                    uint8_t r = (uint8_t)fminf(fmaxf(sinTimeTerm * val, 0.0f), 255.0f);
                    uint8_t g = (uint8_t)fminf(fmaxf(gFactor * val, 0.0f), 255.0f);
                    uint8_t b = (uint8_t)fminf(fmaxf(bFactor * val, 0.0f), 255.0f);

                    L0_setPixel(x, y, r, g, b);
                } else {
                    L0_setPixel(x, y, 0, 0, 0);
                }
            }
        }
    }
}
// >>> LAYER 0 TRANSLATION END <<<

// ── Deterministic pipeline (do not edit) ──
static void rleDecode(const uint8_t* rle, size_t len, uint8_t* out) {
  size_t o = 0;
  const size_t cap = (size_t)PIX_N * 4;
  for (size_t i = 0; i + 4 < len && o < cap; i += 5) {
    for (int k = 0; k < rle[i] && o < cap; k++) {
      out[o++] = rle[i + 1]; out[o++] = rle[i + 2]; out[o++] = rle[i + 3]; out[o++] = rle[i + 4];
    }
  }
}

// Binary mask test — identical to the Pattern Lab preview: pixel art is "on"
// where something was drawn (alpha >= 0.5); code layers where ramp-colored
// luminance x alpha crosses 0.5.
static inline bool maskOn(const uint8_t* p, bool pixelArt, bool invert) {
  bool on;
  if (pixelArt) on = p[3] >= 128;
  else on = (0.2126f * p[0] + 0.7152f * p[1] + 0.0722f * p[2]) * (p[3] / 255.0f) >= 127.5f;
  return invert ? !on : on;
}

static void recolorBuffer(uint8_t* buf, const uint8_t lut[256][4]) {
  for (int i = 0; i < PIX_N; i++) {
    uint8_t* p = buf + (size_t)i * 4;
    if (p[3] == 0) continue;
    int lum = (int)(0.2126f * p[0] + 0.7152f * p[1] + 0.0722f * p[2] + 0.5f);
    if (lum > 255) lum = 255;
    const uint8_t* c = lut[lum];
    p[0] = c[0]; p[1] = c[1]; p[2] = c[2]; p[3] = c[3];
  }
}

void setup() {
  for (int i = 0; i < LAYER_N; i++)
    if (!layerBuf[i]) layerBuf[i] = (uint8_t*)PFMem::alloc((size_t)PIX_N * 4);
  for (int i = 0; i < LAYER_N; i++)
    if (!layerBuf[i]) return; // allocation failed → draw() degrades to blank
  rleDecode(L1_RLE, sizeof(L1_RLE), layerBuf[1]);
  L0::setup();
}

void update(float dt, const InputFrame& input) {
  for (int i = 0; i < 4; i++) {
    knobVal[i] += input.knobDeltas[i] * KNOB_STEP[i];
    if (knobVal[i] < KNOB_MIN[i]) knobVal[i] = KNOB_MIN[i];
    if (knobVal[i] > KNOB_MAX[i]) knobVal[i] = KNOB_MAX[i];
    knobNorm[i] = (knobVal[i] - KNOB_MIN[i]) / (KNOB_MAX[i] - KNOB_MIN[i]);
  }
  L0::update(dt, input);
}

void draw() {
  PFCanvas::setFrame(FRAME_W, FRAME_H);
  for (int i = 0; i < LAYER_N; i++)
    if (!layerBuf[i]) { PFCanvas::present(); return; }

  memset(layerBuf[0], 0, (size_t)PIX_N * 4);
  L0::draw();
  recolorBuffer(layerBuf[0], L0_RAMP);

  // Composite bottom → top over the panel's black — same math as the web preview.
  for (int y = 0; y < FRAME_H; y++) {
    for (int x = 0; x < FRAME_W; x++) {
      const size_t j = ((size_t)y * FRAME_W + x) << 2;
      float cr = 0.0f, cg = 0.0f, cb = 0.0f;
      for (int gi = 0; gi < GROUP_N; gi++) {
        bool hidden = false;
        for (int m = 0; m < G_MASK_N[gi]; m++) {
          const int mi = G_MASK_AT[gi] + m;
          if (!maskOn(layerBuf[MASK_LAYER[mi]] + j, MASK_PXART[mi] != 0, MASK_INVERT[mi] != 0)) {
            hidden = true;
            break;
          }
        }
        if (hidden) continue;
        const uint8_t* p = layerBuf[G_LAYER[gi]] + j;
        const float a = (p[3] / 255.0f) * G_OPACITY[gi];
        if (a <= 0.0f) continue;
        const float sr = p[0], sg = p[1], sb = p[2], inv = 1.0f - a;
        switch (G_BLEND[gi]) {
          case 1: cr += sr * a; cg += sg * a; cb += sb * a; break;
          case 2:
            cr = cr * inv + (cr * sr / 255.0f) * a;
            cg = cg * inv + (cg * sg / 255.0f) * a;
            cb = cb * inv + (cb * sb / 255.0f) * a;
            break;
          case 3:
            cr = cr * inv + (255.0f - (255.0f - cr) * (255.0f - sr) / 255.0f) * a;
            cg = cg * inv + (255.0f - (255.0f - cg) * (255.0f - sg) / 255.0f) * a;
            cb = cb * inv + (255.0f - (255.0f - cb) * (255.0f - sb) / 255.0f) * a;
            break;
          default:
            cr = cr * inv + sr * a;
            cg = cg * inv + sg * a;
            cb = cb * inv + sb * a;
            break;
        }
      }
      int ir = (int)(cr + 0.5f); if (ir > 255) ir = 255;
      int ig = (int)(cg + 0.5f); if (ig > 255) ig = 255;
      int ib = (int)(cb + 0.5f); if (ib > 255) ib = 255;
      PFCanvas::setPixel(x, y, (uint8_t)ir, (uint8_t)ig, (uint8_t)ib);
    }
  }
  PFCanvas::present();
}

